CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS buyers (id TEXT PRIMARY KEY,name TEXT NOT NULL,country TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('ACTIVE','INACTIVE')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rfqs (id TEXT PRIMARY KEY,buyer_id TEXT NOT NULL REFERENCES buyers(id),reference TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN ('OPEN','QUOTED','WON','LOST')),currency TEXT NOT NULL,estimated_value NUMERIC(18,2) NOT NULL CHECK(estimated_value>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY,actor_user_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS audit_events_entity_idx ON audit_events(entity_type,entity_id,created_at DESC);